update public.trivia_questions set question = 'What is a bride''s trousseau?', options = '["The clothes and linens she gathers for married life", "Her wedding veil", "The top tier of the wedding cake", "The cushion that carries the rings"]'::jsonb, correct_answer = 'The clothes and linens she gathers for married life', difficulty = 'medium', explanation = null
where question = 'What is the traditional gift for a 10th wedding anniversary?';
update public.trivia_questions set question = 'In chess, which piece can only ever move diagonally?', options = '["Bishop", "Rook", "Knight", "Queen"]'::jsonb, correct_answer = 'Bishop', difficulty = 'easy', explanation = null
where question = 'Which board game has players buying properties and collecting rent?';
update public.trivia_questions set question = 'In 2002, which country became the first to legalise euthanasia nationwide?', options = '["The Netherlands", "Belgium", "Switzerland", "Canada"]'::jsonb, correct_answer = 'The Netherlands', difficulty = 'hard', explanation = 'Belgium followed a month later.'
