update public.trivia_questions set question = 'Which archbishop chaired South Africa''s Truth and Reconciliation Commission?', options = '["Desmond Tutu", "Nelson Mandela", "F. W. de Klerk", "Steve Biko"]'::jsonb, correct_answer = 'Desmond Tutu', difficulty = 'medium', explanation = null
where question = 'Which South African leader spent 27 years in prison before becoming the country''s first Black president?';
update public.trivia_questions set question = 'Which writer advised rulers that it is safer to be feared than loved, in The Prince?', options = '["Niccolò Machiavelli", "Thomas Hobbes", "Plato", "Sun Tzu"]'::jsonb, correct_answer = 'Niccolò Machiavelli', difficulty = 'medium', explanation = null
where question = 'Which ancient Chinese philosopher taught that respect, family loyalty and moral conduct were the foundations of a good society?';
update public.trivia_questions set question = 'Something old, something new, something borrowed and what else does a bride traditionally carry?', options = '["Something blue", "Something gold", "Something sweet", "Something white"]'::jsonb, correct_answer = 'Something blue', difficulty = 'easy', explanation = null
